import numpy as np
def priority_v2(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Normalize free space (EMP) using logistic function to emphasize stacks with more free space
    if SH == 0:
        normalized_EMP = 1.0  # Empty stack is best
    else:
        normalized_EMP = 1 / (1 + np.exp(-0.5 * (EMP - 2)))  # Logistic scaling

    # Normalize average ID (AVG) to prefer stacks with lower average IDs
    if AVG == 0:
        normalized_Avg = 1.0  # Empty stack has no blocking containers
    else:
        normalized_Avg = 1 / (1 + np.exp(0.5 * (AVG - CUR)))  # Lower AVG is better

    # Normalize RI (number of containers in the stack with smaller ID than CUR)
    normalized_RI = 1 / (1 + np.exp(0.5 * (RI - 1)))  # Lower RI is better

    # Normalize DIFF (smallest ID in the stack minus CUR)
    if DIFF == 2.1e9:
        normalized_DIFF = 1.0  # Empty stack has no potential relocations
    else:
        normalized_DIFF = 1 / (1 + np.exp(0.5 * (DIFF - 100)))  # Lower DIFF is better

    # Combine all factors with adjusted weights
    priority = - (0.4 * normalized_EMP) - (0.3 * normalized_Avg) - (0.2 * normalized_RI) - (0.1 * normalized_DIFF)
    return priority
